<template><el-dialog v-model="visible" title="确认预约订单" width="min(480px, 94vw)" class="booking-payment" :close-on-click-modal="false" :close-on-press-escape="!sending" :show-close="!sending" append-to-body destroy-on-close><div class="payment-amount"><span>预约服务费 · 全额</span><strong>¥ {{Number(order.yuyuejiage||0).toFixed(2)}}</strong></div><dl><dt>订单编号</dt><dd>#{{order.id}}</dd><dt>服务摄影师</dt><dd>{{order.sheyingxingming}}</dd><dt>拍摄时间</dt><dd>{{order.yuyuesheyingriqi}} {{order.yuyueshijianduan}}</dd><dt>订单管理方</dt><dd>花海摄影工作室</dd></dl><el-form label-position="top"><el-form-item label="选择支付方式"><el-radio-group v-model="channel" class="payment-channels"><el-radio border label="微信支付">微信支付</el-radio><el-radio border label="支付宝">支付宝</el-radio><el-radio border label="银行卡">银行卡</el-radio><el-radio border label="云闪付">云闪付</el-radio></el-radio-group></el-form-item></el-form><el-checkbox v-model="confirmed" class="payment-confirm">我已核对拍摄时间、摄影师和订单金额</el-checkbox><template #footer><el-button :disabled="sending" @click="visible=false">暂不付款</el-button><el-button type="primary" :disabled="!confirmed" :loading="sending" @click="submit">确认支付</el-button></template></el-dialog></template>
<script setup>
import {ref,getCurrentInstance} from 'vue'
const ctx=getCurrentInstance().appContext.config.globalProperties,emit=defineEmits(['payChange','cancel','close'])
const visible=ref(false),order=ref({}),sending=ref(false),confirmed=ref(false),channel=ref('微信支付')
function payClick(table,row){if(table!=='sheyingshiyuyue'||row.sfsh!=='是'||row.ispay==='已支付'){ctx.$toolUtil.message('仅已确认且未付款的预约可以付款','warning');return}order.value={...row};confirmed.value=false;channel.value='微信支付';visible.value=true}
async function submit(){if(!confirmed.value||sending.value)return;sending.value=true;try{await ctx.$http.post('sheyingshiyuyue/pay/'+order.value.id,{channel:channel.value});visible.value=false;ctx.$toolUtil.message('支付完成','success');emit('payChange')}catch{ctx.$toolUtil.message('支付未完成，请刷新订单后重试','error')}finally{sending.value=false}}
defineExpose({payClick})
</script>
<style>
.booking-payment{border-radius:12px}.booking-payment .el-dialog__body{padding:20px 24px}.payment-amount{text-align:center;padding:10px 0 24px}.payment-amount span{font-size:12px;color:#8a9684}.payment-amount strong{display:block;margin-top:12px;font-size:34px;font-weight:500;color:#305d4c}.booking-payment dl{display:grid;grid-template-columns:90px 1fr;gap:18px;font-size:13px;margin:0 0 24px}.booking-payment dt{color:#8a9684}.booking-payment dd{margin:0;color:#3c5142;overflow-wrap:anywhere}.payment-confirm{margin-top:20px;max-width:100%;height:auto;white-space:normal}.payment-confirm .el-checkbox__label{white-space:normal;font-size:12px;line-height:1.8}.booking-payment .el-button--primary{background:#305d4c;border-color:#305d4c}
</style>
<style>.payment-channels{display:grid;grid-template-columns:1fr 1fr;gap:10px;width:100%}.payment-channels .el-radio{margin:0;width:100%;height:44px;border-radius:7px}.payment-channels .el-radio.is-checked{background:#edf3ec;border-color:#305d4c}.payment-channels .el-radio__label{font-size:13px}</style>